local Groups={byId={buff={},debuff={}},groups={},counts={},names={}}
for kind,list in pairs(catalog) do
  for name,ids in pairs(list) do
    local key=kind..':'..name
    Groups.groups[key]=ids
    Groups.counts[key]=#ids
    Groups.names[key]=name
    for _,id in ipairs(ids) do
      Groups.byId[kind][id]=key
    end
  end
end
function Groups.Find(kind,id)
  local index=Groups.byId[kind]
  return index and index[tonumber(id)] or nil
end
function Groups.Members(key) return Groups.groups[key] end
function Groups.Count(key) return Groups.counts[key] or 0 end
function Groups.Name(key) return Groups.names[key] end
function Groups.Contains(key,id)
  local colon=type(key)=="string" and key:find(":",1,true)
  if not colon then return false end
  local kind=key:sub(1,colon-1)
  return Groups.Find(kind,id)==key
end
RamaladniEffectGroups=Groups
